package com.hbm.tileentity.machine.rbmk;
 import com.hbm.api.redstoneoverradio.IRORInteractive; import com.hbm.blocks.machine.rbmk.RBMKControl; import com.hbm.interfaces.ICopiable; import com.hbm.inventory.container.MenuRBMKControl; import dev.golem.core.data.*; import net.minecraft.core.BlockPos; import net.minecraft.nbt.CompoundTag; import net.minecraft.network.RegistryFriendlyByteBuf; import net.minecraft.network.chat.Component; import net.minecraft.util.Mth; import net.minecraft.world.*; import net.minecraft.world.entity.player.*; import net.minecraft.world.inventory.AbstractContainerMenu; import net.minecraft.world.level.Level; import net.minecraft.world.level.block.state.BlockState; import org.jspecify.annotations.Nullable;
 public class BlockEntityRBMKControlManual extends BlockEntityRBMKControl implements MenuProvider, ICopiable, IRORInteractive {
 public @Nullable RBMKColor color; public double startingLevel; public BlockEntityRBMKControlManual(BlockPos p,BlockState s){super(com.hbm.tileentity.ModRBMKBlockEntities.RBMK_CONTROL.get(),p,s);}@Override public String getDefaultName(){return "container.rbmk_control";}@Override public boolean isModerated(){return getBlockState().getBlock() instanceof RBMKControl c&&c.moderated;}@Override public void setTarget(double t){startingLevel=level;super.setTarget(t);}@Override public double getMult(){return targetLevel<startingLevel&&Math.abs(level-targetLevel)>.01D?level+Math.sin(Math.pow(1D-level,15)*Math.PI)*(startingLevel-targetLevel)*RBMKDials.getSurgeMod(getLevel()):level;}
  @Override public void receiveControl(CompoundTag d){super.receiveControl(d);if(Tags.hasInt(d,"color")){int c=Tags.getIntOr(d,"color",-1);color=c<0?null:RBMKColor.VALUES[Mth.clamp(c,0,RBMKColor.VALUES.length-1)];}}@Override protected void loadData(DataIn i){super.loadData(i);int c=i.getIntOr("color",-1);color=c<0?null:RBMKColor.VALUES[Mth.clamp(c,0,RBMKColor.VALUES.length-1)];startingLevel=i.getDoubleOr("startingLevel",level);}@Override protected void saveData(DataOut o){super.saveData(o);o.putInt("color",color==null?-1:color.ordinal());o.putDouble("startingLevel",startingLevel);}@Override public void serialize(RegistryFriendlyByteBuf b){super.serialize(b);b.writeByte(color==null?-1:color.ordinal());}@Override public void deserialize(RegistryFriendlyByteBuf b){super.deserialize(b);int c=b.readByte();color=c<0?null:RBMKColor.VALUES[Mth.clamp(c,0,RBMKColor.VALUES.length-1)];}
  @Override public RBMKColumnType getConsoleType(){return RBMKColumnType.CONTROL;}@Override public RBMKColumn getConsoleData(){RBMKColumn.ControlColumn c=(RBMKColumn.ControlColumn)super.getConsoleData();c.color=color==null?-1:(short)color.ordinal();return c;}@Override public CompoundTag getSettings(Level l,BlockPos p){CompoundTag d=new CompoundTag();if(color!=null)d.putInt("color",color.ordinal());return d;}@Override public void pasteSettings(CompoundTag d,int x,Level l,Player p,BlockPos q){color=Tags.hasInt(d,"color")?RBMKColor.VALUES[Math.abs(Tags.getIntOr(d,"color",0)%RBMKColor.VALUES.length)]:null;markChanged();networkPackNT();}@Override public Component getDisplayName(){return Component.translatable("container.rbmkControl");}@Override public @Nullable AbstractContainerMenu createMenu(int i,Inventory v,Player p){return new MenuRBMKControl(i,v,this);}
  @Override public String[] getFunctionInfo(){return new String[]{PREFIX_VALUE+"extraction",PREFIX_FUNCTION+"setrods"+NAME_SEPARATOR+"percent",PREFIX_FUNCTION+"extendrods"+NAME_SEPARATOR+"percent"};}
  @Override public String runRORFunction(String name,String[] params){if((PREFIX_FUNCTION+"setrods").equals(name)&&params.length>0){setTarget(IRORInteractive.parseInt(params[0],0,100)/100D);markChanged();return null;}if((PREFIX_FUNCTION+"extendrods").equals(name)&&params.length>0){setTarget(Mth.clamp(targetLevel+IRORInteractive.parseInt(params[0],-100,100)/100D,0D,1D));markChanged();}return null;}
 }
